// Kapso envía los mensajes agrupados (debounce): body.data = [ { message, conversation, phone_number_id }, ... ]
// Este nodo junta todos los textos del lote en un solo mensaje para el agente.
const body = $json.body ?? $json;
const items = Array.isArray(body.data) ? body.data : [body];

const textos = [];
let from = '';
let phoneNumberId = '';
let nombre = '';

for (const it of items) {
  const msg = it.message ?? {};
  if (msg.kapso?.direction && msg.kapso.direction !== 'inbound') continue; // ignorar mensajes salientes
  from = msg.from || it.conversation?.phone_number || from;
  phoneNumberId = it.phone_number_id || it.conversation?.phone_number_id || phoneNumberId;
  nombre = it.conversation?.contact_name || nombre;

  const texto = msg.text?.body || msg.kapso?.content || '';
  if (texto) textos.push(texto);
  else if (msg.type) textos.push(`[El cliente envió un mensaje de tipo "${msg.type}" que no puedo leer]`);
}

// Si no hay nada que responder, se detiene el flujo
if (!from || textos.length === 0) return [];

return [{
  json: {
    text: textos.join('\n'),
    to: String(from),
    nombre,
    phoneNumberId: String(phoneNumberId || '1347989838397545'),
  },
}];
